head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil16100";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_questrNm", fn: function () { return String(String((dma_pageContext.get("questrNm") ?? ""))); } },
        { childId: "ipt_questrEmail", fn: function () { return String(String((dma_pageContext.get("questrEmail") ?? ""))); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.form_questionForm = { action: "", method: 'post', target: '' };

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil16100.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name txa_quesContn_onkeyup
 * @description 「내용」 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.txa_quesContn_onkeyup = async function(e){
    try {
        await scwin.checkByte($c.util.getComponent("txa_quesContn"))

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil16100.txa_quesContn_onkeyup' }); }
};

/**
 * @method
 * @name txa_quesContn_onchange
 * @description 「내용」 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.txa_quesContn_onchange = async function(e){
    try {
        await scwin.checkByte($c.util.getComponent("txa_quesContn"))

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil16100.txa_quesContn_onchange' }); }
};

/**
 * @method
 * @name btn_Send_onclick
 * @description btn_Send 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Send_onclick = async function(e){
    try {
        await scwin.send()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil16100.btn_Send_onclick' }); }
};

/**
 * @method
 * @name btn_Clear_onclick
 * @description btn_Clear 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Clear_onclick = async function(e){
    try {
        await scwin.clear()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil16100.btn_Clear_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Send
 * @description Send 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Send = async function () {
    const sbmOptions = {
        id: "tx_fn_Send",
        method: "post",
        action: "/support/question.do?method=registerQuestionEmail",
        ref: "dma_SendReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name send
 * @description send 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.send = async function () {
    if (await $c.fil.checkRequired($c.util.getComponent('ipt_quesTitle'))) {
        return;
    }
    if (await (async (c) => { const v = String((c && c.getValue) ? (c.getValue() ?? "") : ""); const max = Number((c && c.getUserData) ? ((c.getUserData("maxByteLength") || c.getUserData("maxLength")) ?? 0) : 0) || 0; if (max && $c.str.getByteLength(v) > max) { const lbl = "질의제목"; await $c.win.alert((lbl ? ("'" + lbl + "' 항목은 ") : "") + "한글 " + (max / 2) + "자, 영문 " + max + "자까지 가능합니다."); return true; } return false; })($c.util.getComponent('ipt_quesTitle'))) {
        return;
    }
    if (await $c.fil.checkRequired($c.util.getComponent('ipt_questrNm'))) {
        return;
    }
    if (await (async (c) => { const v = String((c && c.getValue) ? (c.getValue() ?? "") : ""); const max = Number((c && c.getUserData) ? ((c.getUserData("maxByteLength") || c.getUserData("maxLength")) ?? 0) : 0) || 0; if (max && $c.str.getByteLength(v) > max) { const lbl = "이름"; await $c.win.alert((lbl ? ("'" + lbl + "' 항목은 ") : "") + "한글 " + (max / 2) + "자, 영문 " + max + "자까지 가능합니다."); return true; } return false; })($c.util.getComponent('ipt_questrNm'))) {
        return;
    }
    if (await $c.fil.checkRequired($c.util.getComponent('txa_quesContn'))) {
        return;
    }
    if (!$c.util.isEmpty(($c.util.getComponent('ipt_questrEmail')).getValue())) {
        $c.util.getComponent("ipt_questrEmail").setValue($c.str.trim($c.util.getComponent('ipt_questrEmail').getValue()));
        if (!$c.str.isEmail($c.util.getComponent('ipt_questrEmail').getValue())) {
            return;
        }
    }
    scwin.form_questionForm.action = "/support/question.do?method=registerQuestionEmail";
    await scwin.tx_fn_Send();
};

/**
 * @method
 * @name clear
 * @description clear 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.clear = async function () {
    $c.util.getComponent("ipt_quesTitle").setValue("");
    $c.util.getComponent("txa_quesContn").setValue("");
    await scwin.checkByte($c.util.getComponent('txa_quesContn'));
};

/**
 * @method
 * @name checkByte
 * @description check Byte 처리
 * @param {*} _obj _obj
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkByte = async function (_obj) {
    const standardByte = 800;
    const contnByte = scwin.getByte(_obj);
    const byteCntObj = $c.util.getComponent("txt_byteCnt");
    byteCntObj.innerText = "내용(" + (contnByte) + "/800 byte)";
    if (contnByte > standardByte) {
        await $c.win.alert((contnByte - standardByte) + "바이트가 초과되었습니다. 초과된 내용은 자동삭제됩니다.\n");
        const contnValue = _obj.getValue();
        _obj.setValue(scwin.calcContn(contnValue, standardByte));
        await scwin.checkByte(_obj);
    }
};

/**
 * @method
 * @name getByte
 * @description get Byte 처리
 * @param {*} _obj _obj
 * @returns {void}
 * @hidden N
 */
scwin.getByte = function (_obj) {
    const sTmpCntnt = new String(_obj.getValue());
    let iCounts = 0;
    for (let i = 0; i < sTmpCntnt.length; i++) {
        const escapeChar = escape(sTmpCntnt.charAt(i));
        if (escapeChar === '%0D') {
            inc = 1;
        } else {
            if (escapeChar.length > 4) {
                iCounts += 2;
            } else {
                iCounts++;
            }
        }
    }
    return iCounts;
};

/**
 * @method
 * @name calcContn
 * @description calc Contn 처리
 * @param {*} _contn _contn
 * @param {*} _maximum _maximum
 * @returns {void}
 * @hidden N
 */
scwin.calcContn = function (_contn, _maximum) {
    let rContn = "";
    let nbytes = 0;
    for (let i = 0; i < _contn.length; i++) {
        const ch = _contn.charAt(i);
        let inc = 0;
        if (ch === '\n') {
            if (_contn.charAt(i - 1) !== '\r') {
                inc = 1;
            }
        } else {
            if (escape(ch).length > 4) {
                inc = 2;
            } else {
                if (ch === '<' || ch === '>') {
                    inc = 4;
                } else {
                    inc = 1;
                }
            }
        }
        nbytes += inc;
        if (nbytes > _maximum) {
            break;
        }
        rContn += ch;
    }
    return rContn;
};
